import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DATASET.md","filePath":"manual-en/DATASET.md","lastUpdated":1785684581000}'),d={name:"manual-en/DATASET.md"};function i(o,e,c,h,m,T){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h3 id="_8-4-dataset-commands" tabindex="-1">8.4 DATASET commands <a class="header-anchor" href="#_8-4-dataset-commands" aria-label="Permalink to &quot;8.4 DATASET commands&quot;">​</a></h3><pre><code>DATASET NAME name [WINDOW={ASIS,FRONT}].
DATASET ACTIVATE name [WINDOW={ASIS,FRONT}].
DATASET COPY name [WINDOW={MINIMIZED,HIDDEN,FRONT}].
DATASET DECLARE name [WINDOW={MINIMIZED,HIDDEN,FRONT}].
DATASET CLOSE {name,*,ALL}.
DATASET DISPLAY.
</code></pre><p>The <code>DATASET</code> commands simplify use of multiple datasets within a PSPP session. They allow datasets to be created and destroyed. At any given time, most PSPP commands work with a single dataset, called the active dataset.</p><p>The DATASET NAME command gives the active dataset the specified name, or if it already had a name, it renames it. If another dataset already had the given name, that dataset is deleted.</p><p>The DATASET ACTIVATE command selects the named dataset, which must already exist, as the active dataset. Before switching the active dataset, any pending transformations are executed, as if <code>EXECUTE</code> had been specified. If the active dataset is unnamed before switching, then it is deleted and becomes unavailable after switching.</p><p>The DATASET COPY command creates a new dataset with the specified name, whose contents are a copy of the active dataset. Any pending transformations are executed, as if <code>EXECUTE</code> had been specified, before making the copy. If a dataset with the given name already exists, it is replaced. If the name is the name of the active dataset, then the active dataset becomes unnamed.</p><p>The DATASET DECLARE command creates a new dataset that is initially “empty,” that is, it has no dictionary or data. If a dataset with the given name already exists, this has no effect. The new dataset can be used with commands that support output to a dataset, <em>e.g.</em> AGGREGATE (see <a href="./AGGREGATE">AGGREGATE</a>).</p><p>The DATASET CLOSE command deletes a dataset. If the active dataset is specified by name, or if ‘*’ is specified, then the active dataset becomes unnamed. If a different dataset is specified by name, then it is deleted and becomes unavailable. Specifying ALL deletes all datasets except for the active dataset, which becomes unnamed.</p><p>The DATASET DISPLAY command lists all the currently defined datasets.</p><p>Many DATASET commands accept an optional <code>WINDOW</code> subcommand. In the PSPPIRE GUI, the value given for this subcommand influences how the dataset’s window is displayed. Outside the GUI, the <code>WINDOW</code> subcommand has no effect. The valid values are:</p><p>ASIS</p><p>Do not change how the window is displayed. This is the default for DATASET NAME and DATASET ACTIVATE.</p><p>FRONT</p><p>Raise the dataset’s window to the top. Make it the default dataset for running syntax.</p><p>MINIMIZED</p><p>Display the window “minimized” to an icon. Prefer other datasets for running syntax. This is the default for DATASET COPY and DATASET DECLARE.</p><p>HIDDEN</p><p>Hide the dataset’s window. Prefer other datasets for running syntax.</p>`,18)])])}const p=a(d,[["render",i]]);export{r as __pageData,p as default};
